"""Reviewed first supplied part, keeping examples and subsection-level reasoning."""

def controls(Body):
 b=Body()
 b.p('對應供稿題號 P3-Q113。本章先理解控制的用途，再分清實施形式、功能與縱深防禦。','Reference P3-Q113. First understand what controls do, then distinguish implementation categories, functions and defense in depth.')
 b.h('p1-firewall-limit','1. 為什麼資訊安全不能只依靠防火牆？','1. Why is a firewall insufficient on its own?')
 b.p('想像一家公司的重要客戶資料都在機房。公司買了昂貴的防火牆，也裝了防毒軟體，某天卻有人直接走進機房，把伺服器硬碟帶走。問題在於防火牆主要管理網路流量，無法取代實體門禁。','Imagine a company keeping important customer data in a server room. It buys an expensive firewall and installs antivirus software, but someone walks into the room and removes a server drive. A firewall primarily manages network traffic; it cannot replace physical access control.')
 b.p('Security Controls（安全控制）是組織為降低安全風險採取的保護措施。它可以是軟體、制度、一名保全或一把門鎖；NIST 的控制概念也包含技術、人員、管理與實體環境相關措施。','Security controls are safeguards an organization uses to reduce security risk. A control can be software, a procedure, a guard or a lock. NIST also recognizes safeguards involving technology, people, management and the physical environment.')
 b.h('p1-control-types','2. 安全控制的三種常見實施形式','2. Three common implementation categories')
 b.table([
  ['類型','如何保護','例子'],['Physical Controls｜實體安全控制','以設施與現場人員保護建築、設備及場所','保全、門鎖、圍籬、門禁卡、機房出入管制'],['Technical Controls｜技術安全控制','以軟硬體與技術機制保護系統','防火牆、防毒、加密、多因素驗證'],['Administrative Controls｜管理安全控制','以政策、流程、訓練與責任分工規範安全運作','資安教育訓練、帳號審核、存取權限政策']],
  [['Category','How it protects','Examples'],['Physical controls','Facilities and on-site personnel protect buildings, equipment and locations','Guards, locks, fences, access cards and server-room restrictions'],['Technical controls','Hardware, software and technical mechanisms protect systems','Firewalls, antivirus, encryption and MFA'],['Administrative controls','Policies, procedures, training and assigned responsibilities guide secure operations','Security awareness training, account reviews and access policies']])
 b.p('這是 CEH 入門常見分類，不是所有標準唯一的分類方式。例如 NIST 文獻也有管理、作業與技術控制的分類；閱讀不同標準時，要先確認其分類軸。','This is a common introductory CEH classification, not the only classification used by every standard. NIST publications also use management, operational and technical categories. Identify a standard’s classification axis before comparing its labels.')
 b.h('p1-four-controls','3. 四個容易混淆的技術名詞','3. Four terms that are easy to confuse')
 b.table([
  ['名詞','白話解釋','主要用途'],['Firewall（防火牆）','網路流量的交通警察','依規則允許或阻擋通訊'],['Antivirus（防毒軟體）','偵測與處理惡意程式的工具','降低惡意軟體風險'],['Encryption（加密）','將資料放進有密碼學保護的保險箱','保護資料機密性'],['Security Guard（保全）','在現場管理人員進出','實體安全防護']],
  [['Term','Plain-language meaning','Primary use'],['Firewall','Traffic control for a network','Allow or block communication according to rules'],['Antivirus','A tool to detect and handle malicious programs','Reduce malware risk'],['Encryption','A cryptographically protected safe for information','Protect data confidentiality'],['Security guard','On-site control of people entering and leaving','Physical protection']])
 b.p('例如伺服器只需要對外提供 HTTPS，防火牆可允許必要通訊並阻擋不符合規則的連線。但正常 HTTPS 流量仍可能觸及有漏洞的網站程式，因此部署防火牆不等於網站程式已安全。','For example, a server that only needs external HTTPS access can allow necessary traffic and block connections that violate its firewall rules. Permitted HTTPS traffic can still reach vulnerable application code, so deploying a firewall does not establish that the website application is secure.')
 b.h('p1-defense-depth','4. 什麼是縱深防禦？','4. What is defense in depth?')
 b.p('假設把價值一億元的物品放進保險箱，合理設計不只是一把鎖：建築入口有門禁、內部有保全、重要區域需要額外驗證，保險箱另有獨立的鎖。第一道防線失效，攻擊者也不一定能直接取得物品。','Suppose an item worth NT$100 million is stored in a safe. A reasonable design uses more than one lock: building access control, guards inside, extra verification for important areas and an independent safe lock. Failure of the first defense need not give an attacker direct access to the item.')
 b.diagram('defense')
 b.p('MFA 是 Multi-Factor Authentication（多因素驗證），使用至少兩種不同類型的驗證因素，例如密碼加上實體安全金鑰。縱深防禦的重點是讓不同控制處理不同失敗情況，整合人員、技術與作業能力；產品數量多不自動代表防護有效。','MFA, multi-factor authentication, uses at least two different types of authentication factors, such as a password and a physical security key. Defense in depth combines people, technology and operations so different controls address different failure conditions. A large product count does not automatically make protection effective.')
 b.h('p1-control-functions','5. 依功能分類：另一個判斷軸','5. Classification by function: a different axis')
 b.table([
  ['控制功能','英文','作用'],['預防性','Preventive','事先阻止問題發生'],['偵測性','Detective','發現正在發生或已發生的問題'],['矯正性','Corrective','事故後修正問題'],['復原性','Recovery','協助恢復受影響服務']],
  [['Function','Term','Purpose'],['Prevention','Preventive','Stop a problem before it occurs'],['Detection','Detective','Find a problem during or after its occurrence'],['Correction','Corrective','Correct problems after an incident'],['Recovery','Recovery','Restore affected services']])
 b.p('保全可以阻止未授權者進入，也可能發現可疑活動，因此同一措施能有多種功能。Physical 和 Preventive 不是互斥選項：前者描述如何實施，後者描述發揮什麼作用。','A guard can prevent unauthorized entry and detect suspicious activity, so one control can serve several functions. Physical and preventive are not mutually exclusive: the former describes implementation, while the latter describes function.')
 b.h('p1-q113-reasoning','6. 回到供稿題號 P3-Q113','6. Return to reference P3-Q113')
 b.p('Which of the following is a "Physical" security control? 下列哪一項屬於實體安全控制？','Which of the following is a "Physical" security control? Identify the option that directly protects the physical environment.')
 b.table([['選項','判斷'],['A. Firewall','主要屬於技術控制'],['B. Antivirus','主要屬於技術控制'],['C. Security Guard','實體安全控制'],['D. Encryption','技術性保護機制']],
         [['Option','Reasoning'],['A. Firewall','Primarily a technical control'],['B. Antivirus','Primarily a technical control'],['C. Security Guard','A physical control'],['D. Encryption','A technical protection mechanism']])
 b.p('供稿參考答案 C. Security Guard。辨識 Physical 時，思考現場人員、設施、實際進出與設備保護。','The supplied proposed answer is C, Security Guard. For a physical-control question, think about on-site personnel, facilities, entry and exit, and equipment protection.')
 return b.text

def authorization(Body):
 b=Body()
 b.p('本章連接七筆倫理駭客、授權與安全測試目的的題號。Hacker 在不同時代與情境，可以指擅長理解、修改或探索技術系統的人，也常被用來指入侵者。','This chapter connects seven references about ethical hacking, authorization and testing purposes. Depending on context and period, hacker can mean someone skilled at understanding, modifying or exploring technical systems, or can refer to an intruder.')
 b.h('p1-hacker-meaning','1. 工具相同，授權與目的仍可能不同','1. The same tools can serve different authorization and purposes')
 b.p('CEH 情境中的核心是目的、授權與實際行為。兩人使用同一工具測試公司網站：甲獲正式授權查漏洞；乙未經同意測試，並打算偷取客戶資料。工具相同，授權基礎與目的卻不同，不能用「會不會寫程式」或「用哪套工具」直接區分。','In CEH scenarios, purpose, authorization and actual conduct are central. Two people use the same tool on a company website: one has formal permission to find vulnerabilities; the other lacks consent and intends to steal customer data. Their tools are the same, but authorization and purpose differ. Programming ability or tool choice alone does not distinguish their roles.')
 b.h('p1-hats','2. White Hat、Black Hat、Grey Hat','2. White hat, black hat and grey hat')
 b.diagram('hats')
 b.p('沒有惡意不自動代表合法。假設鄰居家門沒鎖，你覺得是在幫忙確認安全，就直接進屋查看，事後才告訴鄰居。出發點即使良善，也不會自動使進入他人住宅的行為合法；主動網路安全測試同樣需要確認授權。','Lack of malicious intent does not automatically establish legality. Imagine entering a neighbor’s unlocked house to check its security and only telling the neighbor afterward. A helpful intention does not automatically authorize entry; active network security testing likewise requires checking authorization.')
 b.p('Script Kiddie（腳本小子）主要依靠現成工具或攻擊程式，技術理解相對有限，描述的是能力或行為方式，不是與白帽／黑帽對等的授權分類。Blue Hat（藍帽）定義不一致，有時指受邀的外部測試者；它也不等於負責防禦的 Blue Team（藍隊）。題幹明確描述經授權測試、選項有 White Hat 時，通常優先判斷 White Hat。','Script kiddie describes someone relying mainly on ready-made tools or attack programs with limited technical understanding. It concerns skill or behavior rather than an authorization category equivalent to white or black hat. Blue hat has inconsistent definitions and sometimes means an invited external tester; it is not the same as the defensive blue team. Where a question explicitly describes authorized testing and offers white hat, that is usually the best match.')
 b.h('p1-pentest','3. Penetration Testing 是什麼？','3. What is penetration testing?')
 b.p('Penetration Testing（Pentest，滲透測試）可從房屋安全檢查理解：屋主聘請專業人員，在約定條件下模擬入侵；檢查者除了指出窗戶容易打開，也可安全驗證弱點是否造成不當進入。電腦系統的滲透測試同樣是在授權範圍內模擬攻擊，驗證安全機制是否能被繞過。','Penetration testing, or pentesting, resembles a house-security inspection. The owner hires specialists to simulate intrusion under agreed conditions. They can identify a weak window and safely verify whether it permits improper entry. Computer pentesting similarly simulates attacks within authorization to evaluate whether security mechanisms can be bypassed.')
 b.p('NIST SP 800-115 的技術安全測試指引連接規劃、測試、分析與改善；測試成功突破不是工作終點，必須回到風險與修補。','NIST SP 800-115 connects planning, testing, analysis and mitigation. A successful bypass is not the end of the work; findings must inform risk decisions and remediation.')
 b.h('p1-asset-terms','4. 四個核心名詞與評估／測試的差別','4. Four core terms and assessment versus testing')
 b.p('假設銀行有錯誤設定，讓原應受限的資料被無權限者取得。將這個故事拆成以下四個元素：','Suppose a bank misconfiguration exposes restricted data to someone without permission. Separate that scenario into four elements:')
 b.table([['名詞','中文','解釋'],['Asset','資產','需要保護的系統與資料'],['Vulnerability','弱點、漏洞','可能被利用的缺陷'],['Threat','威脅','可能造成損害的行為者、事件或條件'],['Exploit','利用漏洞','透過弱點造成原本不應發生的結果']],
         [['Term','Meaning','Explanation'],['Asset','Something of value','Systems and data needing protection'],['Vulnerability','A weakness','A flaw that may be exploited'],['Threat','A source of potential harm','An actor, event or condition that may cause damage'],['Exploit','Use a vulnerability','Use a weakness to cause a result that should not be permitted']])
 b.p('弱點可能存在於軟體、系統程序、內部控制或實作，不只程式碼錯誤。Vulnerability Assessment（漏洞評估）著重辨識、分析、評估；Pentest 進一步在授權內確認能否被利用及其影響。兩者可交集，但重點不同。','A vulnerability can occur in software, procedures, internal controls or implementation, not just source code. Vulnerability assessment emphasizes identifying, analyzing and evaluating weaknesses; pentesting further checks authorized exploitability and impact. The activities overlap but have different emphases.')
 b.p('例如掃描器發現軟體版本存在已知漏洞，仍要確認漏洞是否適用、是否可被利用；滲透測試可能進一步驗證實際安全影響。因此工具顯示有漏洞，不等於已證明系統成功遭入侵。','For example, a scanner finding a software version associated with a known vulnerability still requires checking applicability and exploitability. A pentest may then verify actual impact. A vulnerability alert does not itself prove that a system has been successfully compromised.')
 b.h('p1-authorization-validity','5. 授權不只是「老闆說可以」','5. Authorization requires more than “the boss said yes”')
 b.p('Authorization 是某項操作獲得適當權限或許可。先確認誰有權允許、哪些系統與活動可測、何時可測、能用哪些方法，以及意外發生如何處理。董事長同意測公司雲端系統，不代表他能替第三方共享平台的其他廠商允許所有活動；授權人的權限與標的都必須確認。','Authorization means receiving appropriate permission for an operation. Establish who can grant permission, which systems and activities are covered, when testing is allowed, permitted methods and incident procedures. A chairperson authorizing tests of company cloud systems may not have authority to permit every activity on a third-party shared platform. Both the grantor’s authority and the target matter.')
 b.h('p1-scope','6. Scope 與 ROE：測試界線','6. Scope and ROE: testing boundaries')
 b.p('Scope（測試範圍）界定可測的系統、網域、IP、帳號或功能。Rules of Engagement（ROE，交戰規則）界定限制與操作程序；兩者互相關聯，但不是同一件事。以下是員工登入系統的虛構約定：','Scope defines the systems, domains, IP addresses, accounts or functions included in testing. Rules of engagement, or ROE, define restrictions and operating procedures. They are related but distinct. The following is a fictional agreement for an employee-login system:')
 b.diagram('roe')
 b.p('發現鄰近的 192.0.2.11 疑似有漏洞，不能順便測試；先確認 Scope，必要時取得正式變更授權。192.0.2.0/24 是文件與教學用途位址。ROE 應在測試前建立，授權的是已定義活動，不是無限制操作。','Discovering a suspected vulnerability at neighboring 192.0.2.11 does not permit testing it opportunistically. Check the scope and obtain a formal change when needed. 192.0.2.0/24 is reserved for documentation. ROE are established before testing and authorize defined activities, not unrestricted operations.')
 b.p('P3-Q124 的供稿參考答案為 C. Always obtain written permission before testing。書面授權有助風險管理與證據保留，但仍須有效、涵蓋實際活動並符合適用法律。','The supplied proposed answer to P3-Q124 is C, Always obtain written permission before testing. Written authorization supports risk management and evidence, but it must still be valid, cover the actual activities and comply with applicable law.')
 b.h('p1-testing-purpose','7. 倫理駭客的真正目標','7. The purpose of ethical hacking')
 b.p('突破系統只是驗證風險的可能方法，真正目的在幫組織理解與處理弱點。以下五步把授權、發現與改善連在一起：','Bypassing a system is one possible way to verify risk. The purpose is to help an organization understand and address weaknesses. These five steps connect authorization, discovery and improvement:')
 b.diagram('testing')
 b.p('EC-Q331 的供稿參考答案 B. To identify and fix security vulnerabilities in a system，這裡 fix 指促成漏洞修補與安全改善，不一定由測試者親自改程式。負責團隊修補後，仍要複測才能確認改善。','For EC-Q331, the supplied answer is B, To identify and fix security vulnerabilities in a system. Fix means enabling remediation and security improvement; the tester does not necessarily modify the application personally. Remediation by the responsible team still needs retesting.')
 return b.text

def overview(Body):
 b=Body()
 b.p('從基礎概念、專有名詞、案例推理到原題解析與新題練習，本部分讓你逐步建立可重複使用的判斷能力。九筆題號屬 M01：倫理駭客、授權與測試目的共七筆，CIA 與實體控制各一筆，因此額外練習後兩類，避免只熟悉高出題比例的觀念。','This part develops reusable judgment through foundational concepts, terminology, scenarios, supplied-question analysis and new exercises. Its nine M01 references comprise seven about ethical hacking, authorization and testing purposes, one about CIA and one about physical controls. Extra attention to the latter two avoids learning only the most frequently represented concept.')
 b.listing(['為什麼有些駭客行為合法，有些不合法？','資訊安全在保護什麼？','保全、防火牆、防毒與加密各有何作用？','英文題目換情境後，如何判斷？','如何確認理解，而非碰巧答對？'],['Why are some hacking activities authorized while others are not?','What does information security protect?','What do guards, firewalls, antivirus and encryption each do?','How can you reason through a reworded English question?','How can you distinguish understanding from a lucky answer?'])
 b.diagram('overview')
 b.p('三個問題有設計上的依賴：先決定保護目標，再建立防護，最後透過授權測試評估效果。以下用診所、銀行與公司案例逐步推理。供稿保留題號、部分題意與選項說明，完整原題尚未全數提供；字母答案是供稿參考，不能據此宣稱已驗證正式題庫。','The three questions have a design dependency: define protection goals, establish safeguards and assess their effect through authorized testing. Clinic, bank and company scenarios make the reasoning concrete. The supplied notes contain question references, partial wording and option analysis, but not every complete original question; answer letters remain supplied proposals rather than verified official exam keys.')
 return b.text

def english(Body):
 b=Body()
 b.p('不必先把題幹每個字完整翻譯；先辨認題目要解決的問題，再找決定性證據。','You need not translate every word before reasoning. Identify the problem being asked, then locate decisive evidence.')
 b.h('p1-question-tree','1. 用決策樹辨認問題類型','1. Use a decision tree to identify the question type')
 b.diagram('decision')
 b.p('這是解題導航，不代表真實問題只能屬一類。多重影響事件仍要依題幹所問的主要問題判斷。','This is navigation for reasoning, not a claim that a real incident fits only one category. For an incident with several impacts, identify the main issue the question asks about.')
 b.h('p1-english-clues','2. 必須看懂的英文線索','2. English clues to understand')
 rows=[['With permission','經過許可','授權','With permission','Authorization'],['Full knowledge and permission','組織知情且允許','White Hat','The organization knows and permits testing','White hat'],['Unauthorized','未經授權','不符合白帽基本條件','Without authorization','Fails a basic white-hat condition'],['Written permission','書面許可','正式授權紀錄','Written consent','A formal authorization record'],['Identify vulnerabilities','找出漏洞','安全測試目的','Find weaknesses','Testing purpose'],['Exploit vulnerabilities','利用漏洞','驗證實際影響','Use weaknesses','Verify actual impact'],['Sensitive information','敏感資訊','可能涉及保密性','Restricted information','Confidentiality may be relevant'],['Intercept traffic','攔截流量','可能影響保密性或完整性','Acquire traffic in transit','Confidentiality or integrity may be affected'],['Modify / Tamper','修改、竄改','Integrity','Change or tamper','Integrity'],['Disrupt services','中斷服務','Availability','Interrupt services','Availability'],['Physical control','實體控制','保全、門鎖、門禁','Physical safeguards','Guards, locks and access controls'],['Primary goal','主要目標','選核心目的','Main objective','Choose the core purpose'],['Best describes','最符合描述','選最貼切答案','Best matching description','Choose the closest match']]
 b.table([['英文','中文意思','判斷方向']]+[[r[0],r[1],r[2]] for r in rows],[['Phrase','Meaning','Reasoning direction']]+[[r[0],r[3],r[4]] for r in rows])
 b.p('尤其注意 primary 和 best：題目不是只問某選項是否「可能相關」，而是要選最直接符合題幹的答案。','Pay particular attention to primary and best. A merely possible association is insufficient; choose the option that most directly fits the question.')
 return b.text

def answers(Body):
 b=Body()
 b.p('將原理帶回九筆題號。以下保留供稿的關鍵措辭與選項判斷，答案是供稿預期答案；未提供的完整題文仍待核對。','Apply the principles to the nine references. The following retains the supplied key wording and option reasoning. These are the supplied expected answers; missing complete question texts still need verification.')
 entries=[
 ('EC-Q001','full knowledge and permission from the organization','D. White Hat Hacking','公司知情並允許滲透測試。Blue Hat 定義不一致；Grey Hat 不符合明確正式授權；Black Hat 與合法安全測試目的不符。','The company knows and permits the pentest. Blue hat has inconsistent definitions; grey hat does not match explicit authorization, and black hat conflicts with the authorized testing purpose.'),
 ('P1-Q003','clear text ... intercepting the traffic ... read the contents','B. Confidentiality','法律文件以明文傳輸，未授權者可能讀取。Availability 問能否使用；Integrity 問不當修改；Non-Repudiation 問反駁否認的證據。','Legal documents travel in cleartext and may be read without permission. Availability concerns usability, integrity concerns improper changes, and non-repudiation concerns evidence against denial.'),
 ('P3-Q113','Physical security control','C. Security Guard','問實施形式。Firewall、Antivirus、Encryption 主要為技術控制；保全管理實際場所進出。','The question concerns implementation category. Firewall, antivirus and encryption are primarily technical; guards control entry into physical locations.'),
 ('EC-Q054','full knowledge and permission','C. White Hat','與 EC-Q001 幾乎同概念，只改選項排序；記授權條件，不要背 White Hat 一定在 C 或 D。','Almost the same concept as EC-Q001 with reordered options. Remember authorization conditions, not whether white hat appears as C or D.'),
 ('P3-Q124','main ethical rule','C. Always obtain written permission before testing','A 不擇手段取得存取權不符授權界線；B 暗網販賣漏洞不是負責任測試目的；D 不通知受影響所有者不符適當報告與通報。','A, gaining access by any means, ignores authorization boundaries. B, selling vulnerabilities on the dark web, is not the responsible testing purpose. D, withholding notification from affected owners, conflicts with appropriate reporting.'),
 ('EC-Q166','hired to legally assess ... identifying vulnerabilities and attempting to exploit them','D. White Hat','受聘合法評估與驗證漏洞，符合白帽。Grey Hat 不符明確授權；Black Hat 不是合法安全測試角色；Script Kiddie 描述能力或工具使用方式。','Being hired to lawfully assess and verify vulnerabilities matches white hat. Grey hat does not match explicit authorization; black hat is not the lawful testing role; script kiddie describes skill or tool reliance.'),
 ('EC-Q189','main difference between ethical hacking and malicious hacking','C. Ethical hacking is performed with permission, while malicious hacking is unauthorized','A 顛倒合法性；B 誤認兩者必用不同工具；D 誤以單人或團隊區分。這是本題最佳區別，實務還要判斷目的、範圍、法律與行為。','A reverses the authorization distinction. B incorrectly assumes different tools. D incorrectly uses solo versus team work to distinguish roles. This is the best distinction in the question; practice also requires assessing purpose, scope, law and conduct.'),
 ('EC-Q331','primary goal of ethical hacking','B. To identify and fix security vulnerabilities in a system','A 破壞服務、C 竊取資訊、D 散播惡意軟體都不是正當測試主要目的。fix 包含促成負責團隊修補。','A, disrupting service; C, stealing information; and D, spreading malware are not the legitimate primary purpose. Fix includes enabling remediation by the responsible team.'),
 ('EC-Q476','role of a penetration tester','C. Authorized security professional who exploits vulnerabilities','關鍵 Authorized；exploits 指授權內驗證漏洞，不是無限制攻擊。','Authorized is decisive. Exploits here means verifying weaknesses within authorization, not unrestricted attack.')]
 for id,clue,answer,zh,en in entries:
  b.h('p1-analysis-'+id.lower(),id,id)
  b.p('題目線索：'+clue,'Question clue: '+clue)
  b.p('供稿參考答案：'+answer,'Supplied proposed answer: '+answer)
  b.p(zh,en)
 b.table([['概念群組','題數','對應題號'],['白帽與授權','6','EC-Q001、EC-Q054、P3-Q124、EC-Q166、EC-Q189、EC-Q476'],['安全測試目的','1','EC-Q331'],['CIA','1','P1-Q003'],['實體安全控制','1','P3-Q113']],
         [['Concept group','Count','References'],['White hat and authorization','6','EC-Q001, EC-Q054, P3-Q124, EC-Q166, EC-Q189, EC-Q476'],['Testing purpose','1','EC-Q331'],['CIA','1','P1-Q003'],['Physical control','1','P3-Q113']])
 b.p('九題反覆測量幾個原則；應建立可重複使用的推理，不把它們當成九個孤立答案。','The nine references repeatedly test a few principles. Develop reusable reasoning rather than treating them as nine isolated answers.')
 return b.text

def practice(Body):
 b=Body()
 b.p('換情境與選項順序，才能檢查是否理解。原供稿規劃 10 題並描述「答錯先提示、答對再顯示完整解釋」的練習方式，但附件實際只提供第 1 題；本頁完整保留該題，不將其餘九題或首次答對數當成已提供功能。','Changing the scenario and option order tests understanding. The source planned ten questions and described hints after mistakes followed by a full explanation after a correct response, but the attachment supplies only question 1. This page retains that complete question without claiming the missing nine questions or a first-attempt score are available.')
 b.p('先獨立作答，再查看參考解析；本頁檢核只在瀏覽器處理，不儲存、不外送。以下解析由正文原理補成，與未提供的原始答案介面分開。','Answer independently before reading the explanations. This page checks answers only in the browser, without saving or transmitting them. The explanations below are editorial additions based on the body, separate from the missing source answer interface.')
 zh={'id':'p1-supplied-practice-1','prompt':'一名資安顧問被授權測試 A 伺服器。他發現 B 伺服器也可能存在相同漏洞，但 B 不在授權範圍內。下一步最適當的是什麼？','options':['A. 因為已經是白帽駭客，所以可以一起測試','B. 先向授權方確認並申請變更測試範圍','C. 只測試一次就不算越權','D. 只要最後交出報告，就可以先測試'],'answer':1,'rationales':['角色稱呼不會擴大有效授權。','先確認授權與正式變更，再依核准範圍測試。','測試次數不決定是否越權。','事後交報告不能取代事前授權。']}
 en={'id':zh['id'],'prompt':'A consultant is authorized to test server A and suspects the same vulnerability on server B, which is outside scope. What is the best next step?','options':['A. Test both because the consultant is already a white hat','B. Confirm with the authorization owner and request a scope change','C. Testing only once cannot exceed authorization','D. Test first as long as a report is delivered afterward'],'answer':1,'rationales':['A role label does not expand valid authorization.','Confirm permission and formal scope changes before testing.','The number of attempts does not determine authorization.','A later report cannot replace prior authorization.']}
 for lang,q in [('zh',zh),('en',en)]:b.text[lang].append({'kind':'checks','items':[q]})
 b.h('p1-learning-standard','如何判斷是否達到學習標準？','How should learning be assessed?')
 b.table([['層次','建議標準'],['基礎認知','不看筆記，用自己的話解釋 CIA、授權與安全控制'],['情境辨識','原設計是 10 題首次全對且能解釋理由；本頁僅有已提供的 1 題，不能據此完成十題驗收'],['遷移應用','面對新綜合案例，辨別主要問題、測試界線與適當控制']],
         [['Level','Suggested criterion'],['Foundational understanding','Explain CIA, authorization and controls in your own words without notes'],['Scenario recognition','The source planned ten correct first attempts with reasons. Only one supplied question is available here, so the ten-question criterion cannot be completed from this page'],['Transfer','Identify the main problem, testing boundary and appropriate controls in an unseen combined scenario']])
 b.p('這是供稿課程的學習標準，不是 CEH 官方及格門檻。單次全對也不保證長期保留；仍需間隔複習與不同情境複測。','These are the supplied lesson’s learning criteria, not official CEH passing requirements. One perfect attempt does not establish long-term retention; use spaced review and different scenarios.')
 return b.text

def case(Body):
 b=Body()
 b.h('p1-medical-case','情境：某醫療機構的資安測試','Scenario: testing a medical institution')
 b.p('醫療機構委託外部資安公司測試，雙方簽署正式授權，範圍為病患預約系統。測試人員發現：','A medical institution hires an external security company and signs formal authorization covering the patient-appointment system. The testers find:')
 b.listing(['情況 A：傳輸病患聯絡資料時缺乏適當加密，第三人可能讀取。','情況 B：功能的權限檢查有問題，未授權者可能修改預約時間。','情況 C：缺乏足夠可用性保護，大量惡意請求可能中斷預約服務。','情況 D：另有醫療影像系統，但未列入範圍。','情況 E：機房設有防火牆，卻任何人都可直接進入。'],['A: patient contact details travel without suitable encryption and may be read by a third party.','B: an authorization-check flaw may let unauthorized people change appointment times.','C: insufficient availability protection means heavy malicious requests may interrupt appointments.','D: another medical-imaging system exists but is outside scope.','E: the server room has a firewall, but anyone can physically enter.'])
 b.listing(['1. A、B、C 分別主要影響 CIA 哪一項？為什麼？','2. 能直接對 D 的系統做滲透測試嗎？需要確認什麼？','3. E 暴露哪一類控制不足？建議哪些措施？','4. 報告至少應有哪些資訊，才有助實際改善？','5. 已知漏洞修補後，能宣稱「完全安全」嗎？說明理由。'],['1. Which CIA objective is primarily affected by A, B and C, and why?','2. May the testers directly pentest D? What must they confirm?','3. Which control category is deficient in E, and what would you recommend?','4. What information must a report contain to support practical improvement?','5. Can fixing known vulnerabilities establish “complete security”? Explain.'])
 b.p('先自行用 1–5 編號書寫推理，不提供自動評分。這五題連接安全目標、授權與控制，不是英文背誦；可交由教師或同儕依具體理由逐題檢視，針對缺口補充教學，再換情境複測。','Write your reasoning as answers 1–5; this is not automatically graded. The questions connect objectives, authorization and controls rather than English memorization. A teacher or peer can review the reasoning, address gaps and retest using another scenario.')
 b.p('本部分原理依 NIST FIPS 199、SP 800-115 與 SP 800-53 等來源核對；新情境練習不因此成為 CEH 官方題目。','The principles are checked against sources including NIST FIPS 199, SP 800-115 and SP 800-53. That does not make these new scenario exercises official CEH questions.')
 return b.text

def build_part_one(Body,cia):
 specs=[('p1-overview','課程總覽：先理解整張資安地圖','Overview: build a security map',overview(Body)),('p1-cia','第一章｜資訊安全在保護什麼？CIA','Chapter 1 | What does information security protect? CIA',cia()),('p1-controls','第二章｜安全控制與縱深防禦','Chapter 2 | Security controls and defense in depth',controls(Body)),('p1-authorization','第三章｜倫理駭客、授權與測試','Chapter 3 | Ethical hacking, authorization and testing',authorization(Body)),('p1-english','第四章｜英文 CEH 題目怎麼讀？','Chapter 4 | Reading English CEH questions',english(Body)),('p1-answers','第五章｜九筆題號逐題解析','Chapter 5 | Reasoning through nine references',answers(Body)),('p1-practice','第六章｜新的情境練習與學習標準','Chapter 6 | A new scenario and learning criteria',practice(Body)),('p1-case','第七章｜醫療機構綜合案例','Chapter 7 | Combined medical-institution scenario',case(Body))]
 return {lang:[{'id':id,'heading':zh if lang=='zh' else en,'body':body[lang]} for id,zh,en,body in specs] for lang in ['zh','en']}
